arguments.command:
python -c "import numpy as np; from catboost import CatBoostRegressor; from sklearn.ensemble import ExtraTreesRegressor; d=np.load('birefringence_features.npz'); names=d['columns']; X=d['X']; y=d['y']; sel=(np.std(X[:200],axis=0)>1e-10)&np.array(['chalcchalc' not in s and ('_pp_' not in s) for s in names]); X=X[:,sel]; ix=np.array([6,37,38,39,42,43,48,60,61,63,68,88]); print('ORDER',d['ids'][ix]);
for omit in [[],[11],[132],[75],[11,132],[49],[72]]:
 tr=np.array([i for i in range(200) if i not in omit]); m=CatBoostRegressor(iterations=1000,depth=4,learning_rate=.025,l2_leaf_reg=5,verbose=False,thread_count=4,random_seed=19); m.fit(X[tr],np.sqrt(y[tr])); print('OMIT',omit,'PRED',np.round(np.maximum(0,m.predict(X[200+ix]))**2,3));
m=ExtraTreesRegressor(n_estimators=500,max_features=.7,random_state=17,n_jobs=4); m.fit(X[:200],np.sqrt(y)); leaves=m.apply(X); print('NEAREST TRAINING INFLUENCES');
for j in ix:
 same=leaves[:200]==leaves[200+j]; w=(same/np.maximum(1,same.sum(axis=0))).mean(axis=1); top=np.argsort(-w)[:7]; print(d['ids'][j],[(int(i),d['formulas'][i],round(float(y[i]),3),round(float(w[i]),3)) for i in top])"

